<?php
session_start();require_once '../../config/database.php';require_permission('view_job_applications');verify_csrf();$db=getDB();$msg=$err=null;
if($_SERVER['REQUEST_METHOD']==='POST'&&isset($_POST['status'])){
 try{$id=(int)$_POST['id'];$status=$_POST['status'];if(!in_array($status,['pending','shortlisted','interview','rejected','hired'],true))throw new Exception('Invalid status.');$db->prepare("UPDATE job_applications SET status=? WHERE id=?")->execute([$status,$id]);$msg='Application status updated.';}catch(Throwable $e){$err=$e->getMessage();}}
$apps=$db->query("SELECT a.*,j.title FROM job_applications a JOIN job_postings j ON j.id=a.job_id ORDER BY a.created_at DESC")->fetchAll();
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Job Applications</title><link rel="stylesheet" href="<?php echo BASE_PATH;?>assets/vendor/bootstrap/bootstrap.min.css"><link rel="stylesheet" href="<?php echo BASE_PATH;?>assets/vendor/fontawesome/all.min.css"><link rel="stylesheet" href="<?php echo BASE_PATH;?>assets/css/custom.css"></head><body><?php include BASE_PATH.'includes/header.php';?><div class="d-flex"><?php include BASE_PATH.'includes/sidebar.php';?><main class="main-content flex-grow-1 p-4"><h4 class="mb-4"><i class="fas fa-file-lines me-2"></i>Job Applications</h4><?php if($msg):?><div id="flash-message" data-type="success" data-message="<?php echo h($msg);?>"></div><?php endif;?><?php if($err):?><div id="flash-message" data-type="error" data-message="<?php echo h($err);?>"></div><?php endif;?><div class="card border-0"><div class="table-responsive"><table class="table align-middle mb-0"><thead><tr><th>Applicant</th><th>Position</th><th>Email</th><th>Resume</th><th>Status</th><th>Update</th></tr></thead><tbody><?php foreach($apps as $a):?><tr><td><?php echo h($a['applicant_name']);?></td><td><?php echo h($a['title']);?></td><td><?php echo h($a['email']);?></td><td><span class="text-muted"><?php echo h(basename($a['resume_path']));?></span></td><td><span class="badge bg-primary"><?php echo h(ucfirst($a['status']));?></span></td><td><form method="post" class="d-flex gap-2"><?php echo csrf_field();?><input type="hidden" name="id" value="<?php echo $a['id'];?>"><select name="status" class="form-select form-select-sm"><option>pending</option><option>shortlisted</option><option>interview</option><option>rejected</option><option>hired</option></select><button class="btn btn-sm btn-primary">Save</button></form></td></tr><?php endforeach;?></tbody></table></div></div></main></div><script src="<?php echo BASE_PATH;?>assets/vendor/bootstrap/bootstrap.bundle.min.js"></script><script src="<?php echo BASE_PATH;?>assets/js/script.js"></script></body></html>